/* 리포트 저장(반려동물 행 덮어쓰기) */
INSERT INTO AI_HLTH_RPT (
       PET_SN
     , BASE_YMD
     , RPT_TTL
     , ANLS_CN
     , INPT_HASH
     , RFRSH_NMTM
     , AUTO_RGNR_NMTM
     , CRT_DT
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID
) VALUES (
       #{petSn}
     , #{baseYmd}
     , #{rptTtl}
     , #{anlsCn}
     , #{inptHash}
     , #{rfrshNmtm}
     , #{autoRgnrNmtm}
     , #{crtDt}
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId}
)
ON DUPLICATE KEY UPDATE
       BASE_YMD       = VALUES(BASE_YMD)
     , RPT_TTL        = VALUES(RPT_TTL)
     , ANLS_CN        = VALUES(ANLS_CN)
     , INPT_HASH      = VALUES(INPT_HASH)
     , RFRSH_NMTM     = VALUES(RFRSH_NMTM)
     , AUTO_RGNR_NMTM = VALUES(AUTO_RGNR_NMTM)
     , CRT_DT         = VALUES(CRT_DT)
     , MDFR_ID        = VALUES(MDFR_ID)
     , MDFCN_DT       = NOW()
